import{_ as a,o as t,c as r,a3 as p}from"./chunks/framework.BwzYn71E.js";const u=JSON.parse('{"title":"建立售后(义诊答疑)部门","description":"","frontmatter":{"translationSource":{"title":"建立售后(义诊答疑)部门","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=AnG8YkyaK2VGhXykemIDer","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/establishing-a-customer-support-department"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/establishing-a-customer-support-department"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/establishing-a-customer-support-department"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/establishing-a-customer-support-department"}]]},"headers":[],"relativePath":"zh/establishing-a-customer-support-department.md","filePath":"zh/page-AnG8YkyaK2VGhXykemIDer.md"}'),s={name:"zh/establishing-a-customer-support-department.md"};function o(n,e,i,l,h,d){return t(),r("div",null,[...e[0]||(e[0]=[p('<div class="logistics-content"><h1 id="建立售后-义诊答疑-部门" tabindex="-1">建立售后(义诊答疑)部门 <a class="header-anchor" href="#建立售后-义诊答疑-部门" aria-label="Permalink to &quot;建立售后\\(义诊答疑\\)部门&quot;">​</a></h1><blockquote><p>源页面 ID：<code>AnG8YkyaK2VGhXykemIDer</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=AnG8YkyaK2VGhXykemIDer" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>由于<a href="/endfield-skydoc/zh/issues-with-publishing-results">成果公开流程问题总结</a>，决定建立售后部门</p><p>统计售后相关人员</p><p><span class="mark-grey">#言：售后/答疑应当具有追根溯源解决大部分可能问题的能力，具体来说需要能通过报表基本准确的反推问题而这需要对所有模块的功能有清晰的认识和对自动配平/自适应装置的原理要有基本的认识；当然，需要一定的空余时间处理问题/学习需要的知识</span></p><p>沃：诶，那直播呢🤔直播没写进去吗</p><p>东弓：个人认为直播是问诊的手段和保护方式</p><p>建立相关群聊</p><p><span class="mark-grey">此处不应当放群号，由相关人员手动审核拉入</span></p><p><span id="source-block-DheeoJbZgduO0Z9vZfkSv3"></span></p><h2 id="答疑守则-待编写" tabindex="-1">答疑守则（待编写 <a class="header-anchor" href="#答疑守则-待编写" aria-label="Permalink to &quot;答疑守则（待编写&quot;">​</a></h2><p><span id="source-block-MCp3KAJDxAeiKPQNN5mI57"></span></p><h2 id="用户守则-待编写" tabindex="-1">用户守则（待编写 <a class="header-anchor" href="#用户守则-待编写" aria-label="Permalink to &quot;用户守则（待编写&quot;">​</a></h2><p>有问题多去群/答疑网站并以答疑人员回答为准（虽然答疑人员不一定绝对正确但是不可否认的是他们比多数人更加熟悉产线并随时可以转接开发人员），也就是说不要轻易相信其他渠道的回复，也不要在答疑人员处固执己见。</p><p>应该多看当期产线的视频和文档（文档是正常来说获取蓝图的地方，注意评论区出现的蓝图码可能不是最新版本）和视频，视频对几乎所有必要的操作都会展示而文档中对很多常见问题已做出了回答，提出能通过以上手段解决的问题是对答疑人员不必要的负担（即使是不能全部看懂但是如果努力过也能大幅减小答疑人员的负担），请不要这样消费我们的热情和善意。</p><p><span id="source-block-K1QLU97ywaQqerFz7hD7qK"></span></p><h2 id="售后-答疑报名处" tabindex="-1">售后/答疑报名处 <a class="header-anchor" href="#售后-答疑报名处" aria-label="Permalink to &quot;售后/答疑报名处&quot;">​</a></h2><p>jmy</p><p>东弓与葛冰之</p><p>NH（D-15191）</p><p>凯尔希思衡托</p><p>SSnighter</p><p>Disadvantages</p><p>泥岩___</p><p><span id="source-block-n2NeK8zgbi9dRIjBQcTKpl"></span></p><h2 id="售后-答疑名单" tabindex="-1">售后/答疑名单 <a class="header-anchor" href="#售后-答疑名单" aria-label="Permalink to &quot;售后/答疑名单&quot;">​</a></h2><p><span id="source-block-9fU6RZ0Clraa1KB7ThLxkv"></span></p><h2 id="兜底答疑名单" tabindex="-1">兜底答疑名单 <a class="header-anchor" href="#兜底答疑名单" aria-label="Permalink to &quot;兜底答疑名单&quot;">​</a></h2></div>',1)])])}const k=a(s,[["render",o]]);export{u as __pageData,k as default};
